import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Database connection pool
def get_db():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=int(os.environ.get('DB_PORT', 5432)),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'app_service'),
        password=os.environ.get('DB_PASS', '')
    )

def verify_api_key(api_key):
    """Verify API key against stored hash"""
    expected = os.environ.get('API_KEY_HASH', '')
    return hmac.compare_digest(
        hashlib.sha256(api_key.encode()).hexdigest(),
        expected
    )

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    username = request.args.get('username', '')
    department = request.args.get('dept', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Build search query with filters
    base_query = "SELECT id, username, email, department, role FROM users WHERE 1=1"

    if username:
        # Parameterized - safe
        base_query += " AND username ILIKE %s"
        params = ['%' + username + '%']
    else:
        params = []

    if department:
        # Direct string interpolation - VULNERABLE
        base_query += f" AND department = '{department}'"

    if include_inactive.lower() != 'true':
        base_query += " AND active = true"

    base_query += " ORDER BY username LIMIT 50"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(base_query, params if params else None)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        cur.close()
        conn.close()
        return jsonify({'users': results, 'count': len(results)})
    except psycopg2.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>/permissions', methods=['GET'])
def get_permissions(user_id):
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT permission_name FROM user_permissions WHERE user_id = %s", (user_id,))
    perms = [r[0] for r in cur.fetchall()]
    cur.close()
    conn.close()
    return jsonify({'user_id': user_id, 'permissions': perms})

@app.route('/health', methods=['GET'])
def health():
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT 1")
        cur.close()
        conn.close()
        return jsonify({'status': 'healthy'})
    except Exception:
        return jsonify({'status': 'unhealthy'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
